import numpy as np
t=df['t'];P=df['P'];y=df['dP_dt']
# Fit y = a*t^2/(1+b t^2) + P*(c + d*g(t)) for several g; test by residual correlation
from itertools import product
def tryfit(feats):
    X=np.column_stack(feats); b=np.linalg.lstsq(X,y,rcond=None)[0]
    return np.mean((X@b-y)**2)/np.var(y), b
best=None
for bb in np.linspace(0.05,3,60):
    base=t**2/(1+bb*t**2)
    for name,g in [('t',t),('lnt',np.log(t)),('sqrt',np.sqrt(t)),('1/t',1/t),('exp-t',np.exp(-t)),('t2',t**2),('1/(1+t)',1/(1+t)),('sin',np.sin(t)),('cos',np.cos(t)),('logistic',1/(1+np.exp(-t)))]:
        r,b=tryfit([base,P*g,P**2,np.ones(len(t))])
        r2,b2=tryfit([base,P,P**2*g,np.ones(len(t))])
        for rr,nm,bbv in [(r,'Pg',b),(r2,'P2g',b2)]:
            if best is None or rr<best[0]: best=(rr,bb,name,nm,bbv)
print(best)

